"""Migration of the Meridian CRM 4.2 order_fulfilment workflow."""

from __future__ import annotations

from decimal import Decimal, InvalidOperation
from typing import Any


def _numeric(value: Any) -> Decimal:
    """Apply legacy numeric coercion: absent or empty values are zero."""
    if value is None or value == "":
        return Decimal("0")
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError):
        return Decimal("0")


def _lookup_credit_hold(record: dict, tables: dict) -> str:
    """Perform legacy LOOKUP over the first matching live ACCT_MASTER row."""
    account_id = record.get("ACCT_ID", "")
    for row in tables.get("ACCT_MASTER", []):
        if row.get("DEL_FLG") == "Y":
            continue
        if row.get("ACCT_ID", "") == account_id:
            return row.get("CRED_HOLD", "")
    return ""


def fire(state: str, event: str, record: dict, tables: dict) -> dict:
    """Fire the first matching order_fulfilment transition in document order."""
    result_record = dict(record)

    matched = False
    next_state = state
    audits: list[str] = []
    notifies: list[str] = []

    # E -> A, approve
    if state == "E" and event == "approve":
        if _numeric(record.get("TOT_AMT", "")) > 0:
            matched = True
            next_state = "A"
            audits.append("ORD_APPR")

    # A -> S, ship
    elif state == "A" and event == "ship":
        matched = True
        next_state = "S"
        audits.append("ORD_SHIP")
        notifies.append("shipped")

    # S -> I, invoice
    elif state == "S" and event == "invoice":
        matched = True
        next_state = "I"
        audits.append("ORD_INV")

    # E -> X, cancel
    elif state == "E" and event == "cancel":
        matched = True
        next_state = "X"
        audits.append("ORD_CANC")

    # A -> X, cancel
    elif state == "A" and event == "cancel":
        if _lookup_credit_hold(record, tables) != "Y":
            matched = True
            next_state = "X"
            audits.append("ORD_CANC")

    # I -> X, cancel
    elif state == "I" and event == "cancel":
        matched = True
        next_state = "X"
        audits.append("ORD_CANC_INV")
        notifies.append("credit_note")

    if not matched:
        audits.append("WF_NOMATCH")

    return {
        "state": next_state,
        "record": result_record,
        "audits": audits,
        "notifies": notifies,
        "matched": matched,
    }
